


export type UpdateShipmentRequest = { /** Optional resource version last read by the caller. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "expected_version"?: string; /** Caller-owned identifier for this resource in an external system. Caller-owned shipment identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. minLength: 1. maxLength: 255. */ "external_reference_id"?: string | null; /** External carrier, aggregator, or fulfillment platform name for this shipment. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string | null; /** Caller-owned metadata. Omit this field to leave metadata unchanged. Send an object to merge by key, set a key to null to remove it, or set metadata to null to clear all metadata. An empty object makes no change. Empty strings are stored. Keys starting with flint_ are reserved and cannot be written through the public API. */ "metadata"?: Record<string, string | null> | null; };
